def calculate_total_listening_time(episode_durations):
    total_minutes = sum(episode_durations)
    hours = total_minutes // 60
    remaining_minutes = total_minutes % 60
    return (hours, remaining_minutes)

def count_syllables_in_poem(poem):
    def count_syllables(line):
        vowels = 'aeiouy'
        syllables = 0
        prev_vowel = False
        for char in line.lower():
            if char in vowels:
                if not prev_vowel:
                    syllables += 1
                prev_vowel = True
            else:
                prev_vowel = False
        return syllables

    lines = poem.split('\n')
    syllable_counts = []
    for line in lines:
        syllable_counts.append(count_syllables(line))
    return syllable_counts

def celsius_to_fahrenheit(celsius_temps):
    fahrenheit_temps = []
    for temp in celsius_temps:
        fahrenheit_temp = (temp * 9/5) + 32
        fahrenheit_temps.append(fahrenheit_temp)
    return fahrenheit_temps

def count_vowels(string):
    vowels = 'aeiouAEIOU'
    count = 0
    for char in string:
        if char in vowels:
            count += 1
    return count

def filter_substantial_stories(stories):
    substantial_stories = []
    for story in stories:
        if story['word_count'] >= 500 and story['shares'] > 1000:
            substantial_stories.append(story)
    return substantial_stories

def sort_movies_by_year(movie_list):
    def extract_year(movie_string):
        year = movie_string.split("(")[-1].strip(")")
        title = movie_string.split("(")[0].strip()
        return (int(year), title)

    sorted_movies = sorted(movie_list, key=extract_year)
    formatted_movies = [f"{year}: {title}" for year, title in [extract_year(movie) for movie in sorted_movies]]
    return formatted_movies

def count_eye_movements(directions):
    movement_counts = {}
    for direction in directions:
        if direction in movement_counts:
            movement_counts[direction] += 1
        else:
            movement_counts[direction] = 1
    return movement_counts

def calculate_average_age(cases):
    total_age = 0
    num_cases = len(cases)

    for case in cases:
        total_age += case['age']

    if num_cases > 0:
        average_age = total_age / num_cases
        return round(average_age, 1)
    else:
        return 0.0

def track_peru_performance(events):
    medal_counts = {"gold": 0, "silver": 0, "bronze": 0}

    for event in events:
        medal = event["medal"]
        if medal in medal_counts:
            medal_counts[medal] += 1

    return {medal: count for medal, count in medal_counts.items() if count > 0}

def decode_message(encoded_message):
    decoded_message = ""
    i = 0
    while i < len(encoded_message):
        if encoded_message[i].isdigit():
            ascii_value = int(encoded_message[i:i+3])
            decoded_message += chr(ascii_value)
            i += 3
        else:
            decoded_message += encoded_message[i]
            i += 1
    return decoded_message

def predict_engagement(interaction_history):
    content_types = {}
    for content_type, interactions in interaction_history:
        content_types[content_type] = content_types.get(content_type, 0) + interactions
    return max(content_types, key=content_types.get)

def calculate_average_and_personal_best(scores, current_personal_best):
    average_score = sum(scores) / len(scores)
    new_personal_best = average_score < current_personal_best
    return (average_score, new_personal_best)
